cyber-exam-day-18:
function calculateShannonEntropy(str) {
  if (!str || str.length === 0) return { entropy: 0, isHighEntropySecret: false, status: 'EMPTY_STRING' };
  const freqs = {};
  for (const c of str) freqs[c] = (freqs[c] || 0) + 1;
  let h = 0;
  const len = str.length;
  for (const count of Object.values(freqs)) {
    const p = count / len;
    h -= p * Math.log2(p);
  }
  const roundedH = Number(h.toFixed(4));
  const isSecret = roundedH >= 4.5;
  return {
    evaluatedStringLength: len,
    entropy: roundedH,
    isHighEntropySecret: isSecret,
    status: isSecret ? 'HIGH_ENTROPY_SECRET_DETECTED' : 'STANDARD_LOW_ENTROPY_STRING'
  };
}

