class TrieNode {
  constructor() { this.children = {}; this.isEnd = false; }
}
class Trie {
  constructor() { this.root = new TrieNode(); }
  insert(word) {
    let node = this.root;
    for (const ch of word) node = node.children[ch] || (node.children[ch] = new TrieNode());
    node.isEnd = true;
  }
  search(word) {
    const node = this._walk(word);
    return Boolean(node && node.isEnd);
  }
  startsWith(prefix) { return Boolean(this._walk(prefix)); }
  _walk(text) {
    let node = this.root;
    for (const ch of text) { node = node.children[ch]; if (!node) return null; }
    return node;
  }
}

function findWordsWithPrefix(trie, prefix) {
  let node = trie.root;
  for (const ch of prefix) { node = node.children[ch]; if (!node) return []; }
  const words = [];
  (function collect(n, text) {
    if (n.isEnd) words.push(text);
    for (const ch of Object.keys(n.children)) collect(n.children[ch], text + ch);
  })(node, prefix);
  return words;
}

