function countComponents(n, edges) {
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const seen = new Array(n).fill(false);
  let count = 0;
  for (let v = 0; v < n; v++) {
    if (seen[v]) continue;
    count++;
    const queue = [v]; seen[v] = true;
    while (queue.length) for (const w of adj[queue.shift()]) if (!seen[w]) { seen[w] = true; queue.push(w); }
  }
  return count;
}

