  for (const [course, pre] of prerequisites) { next[pre].push(course); indeg[course]++; }
  const queue = [];
  for (let i = 0; i < numCourses; i++) if (indeg[i] === 0) queue.push(i);
  const order = [];
  while (queue.length) {
    const c = queue.shift();
    order.push(c);
    for (const n of next[c]) if (--indeg[n] === 0) queue.push(n);
  }
  return order.length === numCourses ? order : [];
}

