    return this.parent[x];
  }
  union(x, y) {
    const a = this.find(x), b = this.find(y);
    if (a === b) return false;
    if (this.rank[a] < this.rank[b]) this.parent[a] = b;
    else if (this.rank[a] > this.rank[b]) this.parent[b] = a;
