  };
}

nlp-exam-day-22:
function mergeMostFrequentBpePair(tokens, pair, replacement) {
  const merged = [];
  for (let i = 0; i < tokens.length; i++) {
    if (tokens[i] === pair[0] && tokens[i + 1] === pair[1]) {
      merged.push(replacement);
      i++;
    } else {
      merged.push(tokens[i]);
    }
  }
  return {
    originalCount: tokens.length,
    mergedCount: merged.length,
    mergedTokens: merged,
    status: 'BPE_PAIR_MERGED_NOMINAL'
  };
}

nlp-exam-day-23:
function allocateBertMaskingStrategy(totalCandidates) {
  const maskTokenCount = Math.round(totalCandidates * 0.80);
  const randomTokenCount = Math.round(totalCandidates * 0.10);
  const unchangedCount = totalCandidates - (maskTokenCount + randomTokenCount);
  return {
    totalMaskCandidates: totalCandidates,
    replacedWithMaskToken: maskTokenCount,
    replacedWithRandomToken: randomTokenCount,
    keptUnchanged: unchangedCount,
    status: 'BERT_MASKING_STRATEGY_ALLOCATED_NOMINAL'
  };
}

nlp-exam-day-24:
function generateCausalAttentionMask(seqLen) {
  const mask = [];
  for (let i = 0; i < seqLen; i++) {
    const row = [];
    for (let j = 0; j < seqLen; j++) {
      row.push(j > i ? -Infinity : 0.0);
    }
    mask.push(row);
  }
  return {
    sequenceLength: seqLen,
    maskMatrix: mask,
    status: 'CAUSAL_ATTENTION_MASK_GENERATED_NOMINAL'
  };
}

nlp-exam-day-25:
function selectOptimalAnswerSpan(startL, endL, maxLen) {
  let maxScore = -Infinity;
  let bestStart = 0, bestEnd = 0;
  for (let i = 0; i < startL.length; i++) {
    for (let j = i; j < Math.min(startL.length, i + maxLen); j++) {
      const score = startL[i] + endL[j];
      if (score > maxScore) {
        maxScore = score;
        bestStart = i;
        bestEnd = j;
      }
    }
  }
  return {
    startTokenIndex: bestStart,
    endTokenIndex: bestEnd,
    spanLength: (bestEnd - bestStart) + 1,
    maxJointScore: Number(maxScore.toFixed(4)),
    status: 'OPTIMAL_ANSWER_SPAN_SELECTED_NOMINAL'
  };
}

