  const isApproved = totalN >= k1 && k1 >= k2;
  return {
    totalDocumentsInCorpus: totalN,
    stage1BiEncoderCandidates: k1,
    stage2CrossEncoderReranked: k2,
    isPipelineRatioNominal: isApproved,
    status: isApproved ? 'TWO_STAGE_SEARCH_PIPELINE_VALIDATED_NOMINAL' : 'INVALID_PIPELINE_CANDIDATE_COUNTS'
  };
}

nlp-exam-day-27:
function filterNucleusTopP(probs, topP) {
  const sorted = [...probs].sort((a, b) => b.prob - a.prob);
  const selected = [];
  let cumSum = 0;
  for (const item of sorted) {
    selected.push(item);
    cumSum += item.prob;
    if (cumSum >= topP) break;
  }
  return {
    topPThreshold: topP,
    cumulativeProbability: Number(cumSum.toFixed(4)),
    selectedTokensCount: selected.length,
    selectedTokens: selected,
    status: 'NUCLEUS_TOP_P_FILTERED_NOMINAL'
  };
}

nlp-exam-day-28:
function calculateBrevityPenalty(c, r) {
  if (c > r) return { candidateLen: c, referenceLen: r, brevityPenalty: 1.0, status: 'BLEU_BREVITY_PENALTY_CALCULATED_NOMINAL' };
  const bp = Number(Math.exp(1 - (r / c)).toFixed(4));
  return {
    candidateLen: c,
    referenceLen: r,
    brevityPenalty: bp,
    status: 'BLEU_BREVITY_PENALTY_CALCULATED_NOMINAL'
  };
}

nlp-exam-day-29:
function calculateLoraParameterReduction(d, k, r) {
  const baseParams = d * k;
  const loraParams = r * (d + k);
  const savings = Number(((1 - (loraParams / baseParams)) * 100).toFixed(2));
  return {
    baseParameters: baseParams,
    loraParameters: loraParams,
    rank: r,
    percentageSaved: savings,
    status: 'LORA_PARAMETER_REDUCTION_CALCULATED_NOMINAL'
  };
}

nlp-exam-day-3:
function calculateLaplaceBigramProb(biCount, ctxCount, vocabSize) {
  const prob = Number(((biCount + 1) / (ctxCount + vocabSize)).toFixed(4));
  return {
    bigramCount: biCount,
    contextCount: ctxCount,
    vocabularySize: vocabSize,
    laplaceSmoothedProbability: prob,
    status: 'LAPLACE_SMOOTHED_PROBABILITY_CALCULATED_NOMINAL'
  };
}

