nlp-exam-day-6:
function calculateCosineSimilarity(vecA, vecB) {
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < vecA.length; i++) {
    dot += vecA[i] * vecB[i];
    normA += vecA[i] * vecA[i];
    normB += vecB[i] * vecB[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  const sim = denom === 0 ? 0 : Number((dot / denom).toFixed(4));
  return {
    dotProduct: dot,
    cosineSimilarity: sim,
    isIdenticalDirection: sim === 1.0,
    status: 'COSINE_SIMILARITY_CALCULATED_NOMINAL'
  };
}

nlp-exam-day-7:
function computeVectorAnalogy(a, b, c) {
  const result = [];
  for (let i = 0; i < a.length; i++) {
    result.push(Number((a[i] - b[i] + c[i]).toFixed(4)));
  }
  return {
    dimensions: result.length,
    analogyVector: result,
    status: 'SEMANTIC_VECTOR_ANALOGY_COMPUTED_NOMINAL'
  };
}

nlp-exam-day-8:
function generateCharacterNGrams(word, minN, maxN) {
  const tagged = `<${word}>`;
  const ngrams = [];
  for (let n = minN; n <= maxN; n++) {
    for (let i = 0; i <= tagged.length - n; i++) {
      ngrams.push(tagged.substring(i, i + n));
    }
  }
  ngrams.push(tagged);
  return {
    word,
    minN,
    maxN,
    totalNGrams: ngrams.length,
    ngrams,
    status: 'CHARACTER_NGRAMS_GENERATED_NOMINAL'
  };
}

nlp-exam-day-9:
function calculateGloveWeight(x, xMax, alpha) {
  if (x <= 0) return { coOccurrenceCount: x, weight: 0.0, status: 'GLOVE_WEIGHT_CALCULATED_NOMINAL' };
  const rawRatio = x / xMax;
  const weight = rawRatio >= 1.0 ? 1.0 : Number(Math.pow(rawRatio, alpha).toFixed(4));
  return {
    coOccurrenceCount: x,
    weight,
    isCappedAtMax: weight === 1.0,
    status: 'GLOVE_WEIGHT_CALCULATED_NOMINAL'
  };
}

